lemma span_leadingTerm_eq_span_monomial {G : Set (MvPolynomial σ R)}
    {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) (hG : ∀ g ∈ G, IsUnit (m.leadingCoeff g)) :
    Ideal.span (m.leadingTerm '' ↑G) =
    Ideal.span ((fun p ↦ monomial (m.degree p) (1 : R)) '' (I \ {(0 : MvPolynomial σ R)}))

lemma span_leadingTerm_eq_span_monomial₀ {G : Set (MvPolynomial σ R)}
    {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) (hG : ∀ g ∈ G, IsUnit (m.leadingCoeff g) ∨ g = 0) :
    Ideal.span (m.leadingTerm '' ↑G) =
    Ideal.span ((fun p ↦ monomial (m.degree p) (1 : R)) '' (I \ {(0 : MvPolynomial σ R)}))

lemma isGroebnerBasis_union_of_forall_finite_isGroebnerBasis₀
    {I : Ideal (MvPolynomial σ R)} {σ' : Finset σ → Type*}
    {m' : (s : Finset σ) → MonomialOrder (σ' s)}
    {e : (s : Finset σ) → (m' s).Embedding m}
    {G' : (s : Finset σ) → Set (MvPolynomial (σ' s) R)}
    (hG' : ∀ s, ∀ g ∈ G' s, IsUnit ((m' s).leadingCoeff g) ∨ g = 0)
    (h : ∀ s, ↑s ⊆ Set.range (e s))
    (h' : ∀ s, (m' s).IsGroebnerBasis (G' s) (I.comap <| rename (e s))) :
    m.IsGroebnerBasis (⋃ s : Finset σ, rename (e s) '' G' s) I

theorem isGroebnerBasis_union_of_forall_finite_isGroebnerBasis
    {I : Ideal (MvPolynomial σ R)} {σ' : Finset σ → Type*}
    {m' : (s : Finset σ) → MonomialOrder (σ' s)}
    {e : (s : Finset σ) → (m' s).Embedding m}
    {G' : (s : Finset σ) → Set (MvPolynomial (σ' s) R)}
    (hG' : ∀ s, ∀ g ∈ G' s, IsUnit ((m' s).leadingCoeff g))
    (h : ∀ s, ↑s ⊆ Set.range (e s))
    (h' : ∀ s, (m' s).IsGroebnerBasis (G' s) (I.comap <| rename (e s))) :
    m.IsGroebnerBasis (⋃ s : Finset σ, rename (e s) '' G' s) I

theorem isRemainder_zero_iff_mem_ideal {p : MvPolynomial σ R}
    {G : Set (MvPolynomial σ R)} {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) :
    m.IsRemainder p G 0 ↔ p ∈ I

theorem ideal_eq_span {G : Set (MvPolynomial σ R)} {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) :
    I = Ideal.span G

theorem existsUnique_isRemainder {G : Set (MvPolynomial σ R)}
    {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) (hG : ∀ g ∈ G, IsUnit (m.leadingCoeff g)) (p : MvPolynomial σ R) :
    ∃! (r : MvPolynomial σ R), m.IsRemainder p G r

lemma existsUnique_isRemainder₀ {G : Set (MvPolynomial σ R)}
    {I : Ideal (MvPolynomial σ R)}
    (h : m.IsGroebnerBasis G I) (hG : ∀ g ∈ G, IsUnit (m.leadingCoeff g) ∨ g = 0)
    (p : MvPolynomial σ R) :
    ∃! (r : MvPolynomial σ R), m.IsRemainder p G r

lemma mem_ideal_of_mem_ideal {B : Set (MvPolynomial σ R)} {r : MvPolynomial σ R}
    {I : Ideal (MvPolynomial σ R)} {p : MvPolynomial σ R}
    (hBI : B ⊆ I) (hpBr : m.IsRemainder p B r) (hr : r ∈ I) :
    p ∈ I

lemma term_notMem_span_leadingTerm {p r : MvPolynomial σ R}
    {B : Set (MvPolynomial σ R)} (h : m.IsRemainder p B r) :
    ∀ s ∈ r.support, monomial s (r.coeff s) ∉ Ideal.span (m.leadingTerm '' B)

lemma withBotDegree_remainder_le {f : MvPolynomial σ R} {B : Set (MvPolynomial σ R)}
    {r : MvPolynomial σ R} (h : m.IsRemainder f B r) :
    m.toWithBotSyn (m.withBotDegree r) ≤ m.toWithBotSyn (m.withBotDegree f)

lemma exists_withBotDegree_le_withBotDegree {p : MvPolynomial σ R} {B : Set (MvPolynomial σ R)}
    {r : MvPolynomial σ R}
    (h : m.IsRemainder p B r) (hfr : m.withBotDegree p ≠ m.withBotDegree r) :
    ∃ b ∈ B, m.withBotDegree b ≤ m.withBotDegree p

lemma exists_withBotDegree_le_withBotDegree₀ {p r : MvPolynomial σ R}
    {B : Set (MvPolynomial σ R)}
    (h : m.IsRemainder p B r) (hfr : m.withBotDegree p ≠ m.withBotDegree r) :
    ∃ b ∈ B, b ≠ 0 ∧ m.withBotDegree b ≤ m.withBotDegree p

theorem exists_isRemainder {B : Set (MvPolynomial σ R)}
    (hB : ∀ b ∈ B, IsUnit <| m.leadingCoeff b) (p : MvPolynomial σ R) :
    ∃ (r : MvPolynomial σ R), m.IsRemainder p B r

theorem exists_isRemainder₀ {B : Set (MvPolynomial σ R)}
    (hB : ∀ b ∈ B, (IsUnit (m.leadingCoeff b) ∨ b = 0)) (p : MvPolynomial σ R) :
    ∃ (r : MvPolynomial σ R), m.IsRemainder p B r

lemma mem_ideal_iff {B : Set (MvPolynomial σ R)}
    {r : MvPolynomial σ R} {I : Ideal (MvPolynomial σ R)} {p : MvPolynomial σ R}
    (hBI : B ⊆ I) (hpBr : m.IsRemainder p B r) : r ∈ I ↔ p ∈ I
